export function buildScore(toolkit,document){
 toolkit.select({});toolkit.redoLayout();toolkit.renderToMIDI();const timemap=toolkit.renderToTimemap({includeMeasures:true});const measureVisits=timemap.filter(r=>r.measureOn).map(r=>r.measureOn);if(new Set(measureVisits).size!==measureVisits.length)throw Error('This score expands repeated measures. Unfold repeats in a notation editor and re-import MusicXML before practicing.');const mei=new DOMParser().parseFromString(toolkit.getMEI(),'application/xml');const attr=(e,k)=>e.getAttribute(k);const measures=[...mei.getElementsByTagName('measure')].map((el,i)=>({id:attr(el,'xml:id'),label:attr(el,'n')||String(i+1),index:i}));const starts=new Map(timemap.filter(r=>r.measureOn).map(r=>[r.measureOn,r.qstamp]));let last=0;for(const m of measures){m.start=starts.get(m.id)??last;last=m.start}const end=Math.max(...timemap.map(r=>r.qstamp));measures.forEach((m,i)=>m.end=measures[i+1]?.start??end);
 const segments=[];const byId=new Map();for(const r of timemap){for(const id of r.on||[]){const n=toolkit.getMIDIValuesForElement(id).pitch;if(!Number.isFinite(n))continue;const seg={id,n,t:r.qstamp,end:r.qstamp,root:id};segments.push(seg);byId.set(id,seg)}for(const id of r.off||[]){if(byId.has(id))byId.get(id).end=r.qstamp}}
 const ties=[...mei.getElementsByTagName('tie')].map(e=>[(attr(e,'startid')||'').replace(/^#/,''),(attr(e,'endid')||'').replace(/^#/,'')]);for(let pass=0;pass<ties.length;pass++)for(const [a,b] of ties)if(byId.has(a)&&byId.has(b))byId.get(b).root=byId.get(a).root;
 const events=segments.filter(s=>s.root===s.id).map(s=>({...s,d:Math.max(...segments.filter(n=>n.root===s.id).map(n=>n.end))-s.t}));for(const seg of segments)seg.measure=measures.findIndex(m=>m.start<=seg.t&&seg.t<m.end);
 return {measures,segments,events,end,mei:toolkit.getMEI()};
}
export function passage(score,first,last){if(first<0||last>=score.measures.length||first>last)throw Error('Choose a valid measure range');const start=score.measures[first].start,end=score.measures[last].end;const events=score.events.filter(e=>e.t<end&&e.t+e.d>start).map(e=>({...e,t:Math.max(start,e.t),d:Math.min(end,e.t+e.d)-Math.max(start,e.t)}));const groups=[...new Set(events.map(e=>e.t))].sort((a,b)=>a-b).map(t=>({t,events:events.filter(e=>e.t===t),notes:[...new Set(events.filter(e=>e.t===t).map(e=>e.n))]}));return {start,end,events,groups,first,last};}
export class FollowNotes{constructor(groups){this.groups=groups;this.reset()}reset(){this.index=0;this.collected=new Set();this.active=this.groups.length>0}get current(){return this.groups[this.index]}attack(n){if(!this.active)return'inactive';if(!this.current.notes.includes(n))return'wrong';this.collected.add(n);if(this.current.notes.some(n=>!this.collected.has(n)))return'partial';this.index++;this.collected.clear();if(this.index===this.groups.length){this.active=false;return'finished'}return'advanced'}}
